export interface RawBuiltinSource {
  key: string
  kind: 'online' | 'local'
  updateUrl?: string
  /** 上一版随包写入的地址，用于老用户迁移；用户手动改过的地址不在这份名单里就保持原样 */
  legacyUpdateUrls?: string[]
  /** 主地址全部失败后才尝试的备用地址（同一份脚本的其它线路） */
  fallbackUpdateUrls?: string[]
  /**
   * 本地源脚本头部没写更新地址时，目录替作者补的检查地址（只给本地源用）。
   * {version} 会替换成当前脚本版本；按顺序试，后面的当地址全失败时的备用。
   */
  checkUpdateUrls?: string[]
  /** 是否参加后台自动检查，默认有可用地址就参加；服务器不稳的作者接口可以只留手动检查 */
  autoCheck?: boolean
  autoUpdate?: boolean
  script: string
}

